/**
 * `npm run build:poster` — the configured city's transparency portal poster, in
 * two formats: 1080×1350 (feed, 4:5) and 1080×1080 (square, for Facebook).
 *
 * The sample image is the real portal: screenshots of a running copy (desktop
 * overview, and a project page on a phone), taken when the poster is built.
 * The background uses project titles from this portal's configured scope.
 * Headline and text are typeset here; nothing is generated by an image model.
 *
 * Type and layout follow the BetterGov.PH campaign posters (Anton, Inter,
 * JetBrains Mono on paper, black footer), in BetterGov blue.
 *
 *   npm run dev                          # the sample portal, on :5132
 *   npm run build:poster                 # writes docs/poster/*.png
 *   npm run build:poster -- --site=http://127.0.0.1:5132 --out=docs/poster
 *
 * Needs network access (Google Fonts, the Budget API) and Playwright's Chromium
 * (`npx playwright-core install chromium` if it is not installed).
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { argv, env, exit } from 'node:process';
import { chromium, type Browser } from 'playwright-core';
import config from '../portal.config.ts';
import { createClient } from '../src/api/client.ts';
import { DEFAULT_API, shortNameOf } from '../src/config.ts';
import { date } from '../src/lib/format.ts';
import { resolveScope } from '../src/lib/scope.ts';

const args = Object.fromEntries(
  argv.slice(2).map((a) => {
    const m = /^--([^=]+)(?:=(.*))?$/.exec(a);
    return m ? [m[1], m[2] ?? 'true'] : [a, 'true'];
  }),
);
const ROOT = resolve(import.meta.dirname, '..');
const OUT = resolve(args.out ?? join(ROOT, 'docs/poster'));
const SITE = (args.site ?? 'http://127.0.0.1:5132').replace(/\/+$/, '');
if (!config.siteUrl) throw new Error('Set siteUrl in portal.config.ts before building the city poster.');
const PORTAL_HOST = new URL(config.siteUrl).host;
const VISIT_MARK = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/></svg>';

const api = createClient(env.VITE_API_BASE || config.api || DEFAULT_API);
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const count = (n: number) => n.toLocaleString('en-US');
const dataUri = (buf: Buffer, type: string) => `data:${type};base64,${buf.toString('base64')}`;

// ---------------------------------------------------------------------------
// Data: local project count, date, phone project and background titles
// ---------------------------------------------------------------------------

async function loadData() {
  const scope = await resolveScope(api, config);
  const route = (p: (typeof scope.projects)[number]) => `${p.dataset}/${encodeURIComponent(p.id)}`;
  // A short local title leaves the phone's amount table and source links visible.
  const local = scope.projects.filter((p) => p.title.toLowerCase().includes(config.name.toLowerCase()))
    .sort((a, b) => a.title.length - b.title.length);
  const phoneProject = args.project
    ? scope.projects.find((p) => route(p) === args.project)
    : local.find((p) => p.nep_php !== null && p.nep_php === p.house_php) ?? local[0] ?? scope.projects[0];
  if (!phoneProject) throw new Error('No project in the configured city scope matches the poster request.');
  const wall = scope.projects.map((p) => `<span class="e"><b>${esc(p.title)}</b></span>`);
  return { projects: scope.projects.length, asOf: date(scope.meta.built_at), phoneProject: route(phoneProject), wall };
}

// ---------------------------------------------------------------------------
// Screenshots of the running sample
// ---------------------------------------------------------------------------

async function shoot(browser: Browser, phoneProject: string) {
  const desk = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 2, timezoneId: 'Asia/Manila' });
  await desk.goto(SITE + '/', { waitUntil: 'networkidle' });
  await desk.waitForSelector('.ocard', { timeout: 30000 });
  if (!(await desk.locator('body').innerText()).includes(config.name)) {
    throw new Error(`The screenshot site does not show ${config.name}. Check --site.`);
  }
  // Keep the poster's city focus; this styling affects only the screenshot.
  await desk.addStyleTag({ content: '.build-strip, .masthead-links { display: none !important; }' });
  await desk.evaluate(() => document.fonts.ready);
  const desktop = await desk.screenshot({ clip: { x: 0, y: 0, width: 1280, height: 720 } });

  const phone = await browser.newPage({ viewport: { width: 390, height: 700 }, deviceScaleFactor: 3, isMobile: true, hasTouch: true, timezoneId: 'Asia/Manila' });
  await phone.goto(`${SITE}/projects/${phoneProject}`, { waitUntil: 'networkidle' });
  await phone.waitForSelector('.amounts', { timeout: 30000 });
  await phone.evaluate(() => document.fonts.ready);
  // Start at the title, past the masthead, so the amounts and their pages show.
  await phone.evaluate(() => window.scrollTo(0, (document.querySelector('.crumbs') as HTMLElement).offsetTop - 12));
  const mobile = await phone.screenshot();
  await desk.close();
  await phone.close();
  return { desktop: dataUri(desktop, 'image/png'), mobile: dataUri(mobile, 'image/png') };
}

// ---------------------------------------------------------------------------
// The poster
// ---------------------------------------------------------------------------

interface Format {
  key: string;
  W: number;
  H: number;
}
const FORMATS: Format[] = [
  { key: '1080x1350', W: 1080, H: 1350 },
  { key: '1080x1080', W: 1080, H: 1080 },
];

const LOGO = dataUri(readFileSync(join(ROOT, 'scripts/assets/bettergov-horizontal-white.png')), 'image/png');

function html(f: Format, d: Awaited<ReturnType<typeof loadData>>, shots: { desktop: string; mobile: string }): string {
  const { W, H } = f;
  const u = W / 100;
  const square = W === H;
  const foot = (square ? 13.4 : 15.2) * u;
  const ring = `box-shadow: 0 0 0 ${0.5 * u}px var(--paper)`;
  const name = shortNameOf(config);

  const css = `
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: ${W}px; height: ${H}px; background: #f3eee4; overflow: hidden; }
  .poster { position: relative; width: ${W}px; height: ${H}px; overflow: hidden; --paper: #f3eee4; --ink: #141414; --blue: #0b4fd9; color: var(--ink); background: var(--paper); }
  .wall { position: absolute; left: ${1.4 * u}px; right: ${1.4 * u}px; top: ${1 * u}px; bottom: ${foot + 0.8 * u}px; overflow: hidden;
          font-family: Inter, sans-serif; line-height: 1.32; text-align: justify; hyphens: none; color: rgba(20, 20, 20, 0.2); }
  .wall .e b { font-family: 'JetBrains Mono', monospace; font-weight: 700; color: rgba(11, 79, 217, 0.42); letter-spacing: -0.02em; }
  .wall .e i { font-style: normal; }
  .wall .e::after { content: " ■ "; color: rgba(11, 79, 217, 0.28); }

  .head { position: absolute; left: ${4.6 * u}px; right: ${4.6 * u}px; top: ${(square ? 3.6 : 4.2) * u}px; }
  .kick { display: flex; justify-content: space-between; align-items: baseline; font-family: 'JetBrains Mono', monospace; font-weight: 700;
          font-size: ${(square ? 1.75 : 2) * u}px; letter-spacing: 0.12em; text-transform: uppercase; }
  .kick span { background: var(--paper); ${ring}; }
  .title { margin-top: ${0.9 * u}px; font-family: Anton, Impact, sans-serif; font-weight: 400; line-height: 0.92; text-transform: uppercase; letter-spacing: 0.005em; }
  .title span { display: block; width: fit-content; white-space: nowrap; background: var(--paper); ${ring}; }
  .title .blue { color: var(--blue); }
  .strap { margin-top: ${(square ? 1.4 : 1.8) * u}px; }
  .strap span { display: inline-block; white-space: nowrap; font-family: Anton, Impact, sans-serif; font-size: ${(square ? 3.5 : 4.1) * u}px; line-height: 1;
                text-transform: uppercase; letter-spacing: 0.01em; color: #f3eee4; background: var(--ink); padding: ${0.7 * u}px ${1.4 * u}px ${0.6 * u}px; }
  .sub { margin-top: ${1.7 * u}px; font-family: Inter, sans-serif; font-weight: 700; font-size: ${2.2 * u}px; line-height: 1.32; text-wrap: pretty; }
  .sub span { background: var(--paper); ${ring}; -webkit-box-decoration-break: clone; box-decoration-break: clone; }

  /* The sample: a browser window with the overview, a phone with a project page. */
  .shots { position: absolute; left: ${4.6 * u}px; right: ${4.6 * u}px; }
  .browser { position: relative; width: ${square ? 59 * u : 72 * u}px; border: ${0.25 * u}px solid var(--ink); background: #fff;
             box-shadow: ${1 * u}px ${1 * u}px 0 var(--ink); }
  .browser > .tab { transform: translateY(-100%); left: -${0.25 * u}px; }
  .browser .bar { display: flex; align-items: center; gap: ${0.6 * u}px; height: ${2.6 * u}px; padding: 0 ${1 * u}px; background: #e7e1d5; border-bottom: ${0.2 * u}px solid var(--ink); }
  .browser .bar i { width: ${0.9 * u}px; height: ${0.9 * u}px; border-radius: 50%; background: #141414; opacity: 0.55; }
  .browser .bar span { margin-left: auto; font-family: 'JetBrains Mono', monospace; font-weight: 500; font-size: ${1.15 * u}px; letter-spacing: 0.04em; color: #333; }
  .browser img { display: block; width: 100%; }
  .tab { position: absolute; left: ${1.6 * u}px; top: 0; transform: translateY(-50%); z-index: 2; font-family: 'JetBrains Mono', monospace; font-weight: 700;
         font-size: ${1.3 * u}px; letter-spacing: 0.14em; text-transform: uppercase; color: #fff; background: var(--blue); padding: ${0.35 * u}px ${0.8 * u}px; white-space: nowrap; }
  .phone { position: absolute; right: 0; width: ${square ? 20 * u : 22 * u}px; border: ${0.8 * u}px solid var(--ink); border-radius: ${3 * u}px; overflow: hidden;
           background: #fff; box-shadow: ${1 * u}px ${1 * u}px 0 rgba(20, 20, 20, 0.35); }
  .phone img { display: block; width: 100%; }

  .steps { position: absolute; left: ${4.6 * u}px; right: ${4.6 * u}px; background: var(--paper); border: ${0.25 * u}px solid var(--ink);
           padding: ${(square ? 1.6 : 2) * u}px ${2.2 * u}px ${(square ? 1.3 : 1.6) * u}px; }
  .steps .tab { background: var(--ink); }
  .steps ol { list-style: none; display: grid; grid-template-columns: ${square ? '1fr 1fr 1fr' : '1fr'}; gap: ${(square ? 1.6 : 0.8) * u}px; }
  .steps li { display: grid; grid-template-columns: ${2.3 * u}px 1fr; column-gap: ${1.2 * u}px; align-items: start;
              font-family: Inter, sans-serif; font-weight: 500; font-size: ${(square ? 1.7 : 1.95) * u}px; line-height: 1.3; text-wrap: pretty; }
  .steps li b { display: flex; align-items: center; justify-content: center; width: ${2.3 * u}px; height: ${2.3 * u}px; margin-top: ${0.15 * u}px;
                font-family: Anton, Impact, sans-serif; font-weight: 400; font-size: ${1.6 * u}px; color: #fff; background: var(--blue); }
  .steps code { font-family: 'JetBrains Mono', monospace; font-weight: 700; font-size: 0.9em; background: #e7e1d5; padding: 0 ${0.3 * u}px; }

  .cta { position: absolute; left: ${4.6 * u}px; right: ${4.6 * u}px; }
  .cta span { display: flex; align-items: center; justify-content: center; gap: ${1.3 * u}px; width: 100%; white-space: nowrap;
              font-family: 'JetBrains Mono', monospace; font-weight: 700; font-size: ${(square ? 2.6 : 2.8) * u}px; line-height: 1; letter-spacing: -0.01em;
              color: #fff; background: var(--blue); padding: ${(square ? 1.05 : 1.25) * u}px ${1.5 * u}px; }
  .cta svg { width: 1.15em; height: 1.15em; flex-shrink: 0; }
  .foot { position: absolute; left: 0; right: 0; bottom: 0; height: ${foot}px; background: #111; color: #f3eee4;
          padding: ${(square ? 2 : 2.4) * u}px ${4.6 * u}px; display: grid; grid-template-columns: ${17 * u}px 1fr; column-gap: ${3.4 * u}px; align-items: start;
          font-family: Inter, sans-serif; }
  .foot img { width: ${2.3 * u * (800 / 189)}px; margin-top: ${0.4 * u}px; }
  .foot .url { font-family: 'JetBrains Mono', monospace; font-weight: 700; font-size: ${(square ? 2.05 : 2.25) * u}px; color: #fff; margin-bottom: ${0.7 * u}px; }
  .foot .fine { font-size: ${(square ? 1.15 : 1.25) * u}px; line-height: 1.42; color: rgba(243, 238, 228, 0.85); }
  .foot .fine strong { color: #fff; font-weight: 700; }`;

  const titleSize = (square ? 10.4 : 12.6) * u;
  const steps = [
    `Explore the budget projects listed for ${esc(name)}.`,
    'Compare each project’s NEP and House bill amounts.',
    'Open the source pages. Check the figures for yourself.',
  ];
  const fine =
    `<strong>Community portal by ${esc(config.operator.name)}${config.operator.contributor ? ` and ${esc(config.operator.contributor.name)}` : ''}. Built with BetterGov.PH.</strong> Data: BetterGov.PH Budget API, 2027 NEP and House Bill 10858 (third reading), as of ${d.asOf}. ` +
    `Amounts are as published, not spending. A project in one version only is a candidate to check, not a finding.`;

  return `<!doctype html><html><head><meta charset="utf-8">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;700&display=block" rel="stylesheet">
<style>${css}</style></head><body>
<div class="poster">
  <div class="wall" id="wall"></div>
  <div class="head" id="head">
    <div class="kick"><span>Our city. Our budget. In the open.</span><span>FY 2027 budget</span></div>
    <h1 class="title" style="font-size:${titleSize}px"><span>${esc(config.name)}</span><span class="blue">transparency portal</span></h1>
    <div class="strap"><span>Explore our projects. Check the figures.</span></div>
    ${square ? '' : `<p class="sub"><span>Explore ${esc(name)}’s 2027 budget projects: compare the NEP and House bill, and trace each figure to its source page.</span></p>`}
  </div>
  <div class="shots" id="shots">
    <div class="browser">
      <span class="tab">${esc(config.name)} · ${count(d.projects)} projects</span>
      <div class="bar"><i></i><i></i><i></i><span>${esc(PORTAL_HOST)}</span></div>
      <img src="${shots.desktop}" alt="">
    </div>
    <div class="phone" id="phone"><img src="${shots.mobile}" alt=""></div>
  </div>
  <div class="steps" id="steps">
    <span class="tab">Explore your city’s budget</span>
    <ol>${steps.map((s, i) => `<li><b>${i + 1}</b><span>${s}</span></li>`).join('')}</ol>
  </div>
  <div class="cta" id="cta"><span>${VISIT_MARK}${esc(PORTAL_HOST)}</span></div>
  <div class="foot">
    <img src="${LOGO}" alt="BetterGov.PH">
    <div><p class="url">Made for ${esc(name)}.</p><p class="fine">${fine}</p></div>
  </div>
</div></body></html>`;
}

async function main() {
  mkdirSync(OUT, { recursive: true });
  const data = await loadData();
  const browser = await chromium.launch();
  try {
    const shots = await shoot(browser, data.phoneProject);
    for (const f of FORMATS) {
      const page = await browser.newPage({ viewport: { width: f.W, height: f.H }, deviceScaleFactor: 1 });
      await page.setContent(html(f, data, shots), { waitUntil: 'networkidle' });
      await page.evaluate(() => document.fonts.ready);

      // Stack: head, then the sample, then the steps, spread over the space above the footer.
      const lay = await page.evaluate(({ W, H, square }) => {
        const u = W / 100;
        // The headline at the one size where its widest line fills the width.
        const title = document.querySelector('.title') as HTMLElement;
        const lines = [...title.querySelectorAll('span')] as HTMLElement[];
        const avail = title.getBoundingClientRect().width;
        const size = parseFloat(getComputedStyle(title).fontSize);
        const widest = Math.max(...lines.map((l) => l.getBoundingClientRect().width));
        title.style.fontSize = `${Math.min(size * 1.6, (size * (avail - u)) / widest)}px`;
        const foot = (square ? 13.4 : 15.2) * u;
        const head = document.getElementById('head')!;
        const shots = document.getElementById('shots')!;
        const steps = document.getElementById('steps')!;
        const cta = document.getElementById('cta')!;
        const phone = document.getElementById('phone')!;
        const browser = shots.querySelector('.browser') as HTMLElement;
        const headBottom = head.getBoundingClientRect().bottom;
        const stepsH = steps.getBoundingClientRect().height;
        const ctaH = cta.getBoundingClientRect().height;
        const tabH = (shots.querySelector('.tab') as HTMLElement).getBoundingClientRect().height;

        // The screenshot takes whatever height is left once every gap has its minimum:
        // its width follows (the capture is 1280 × 720), the phone a fixed share of it.
        const minGap = 1.4 * u;
        const chrome = browser.getBoundingClientRect().height - browser.querySelector('img')!.getBoundingClientRect().height;
        const hang = 2 * u; // the phone hangs this far below the browser
        const room = H - foot - headBottom - tabH - stepsH - ctaH - 4 * minGap - hang;
        const maxW = (square ? 62 : 74) * u;
        const width = Math.min(maxW, ((room - chrome) * 1280) / 720);
        browser.style.width = `${width}px`;
        phone.style.width = `${width * (square ? 0.34 : 0.31)}px`;

        // The phone overlaps the browser's lower right corner.
        const browserH = browser.getBoundingClientRect().height;
        const phoneH = phone.getBoundingClientRect().height;
        phone.style.top = `${browserH - phoneH + hang}px`;
        const shotsH = Math.max(browserH + hang, phoneH);

        // Spread what is left over the four gaps: head, sample, steps, GitHub band, footer.
        const free = H - foot - headBottom - tabH - shotsH - stepsH - ctaH;
        const gap = Math.max(minGap * 0.8, free / 4);
        let y = headBottom + gap + tabH;
        shots.style.top = `${y}px`;
        shots.style.height = `${shotsH}px`;
        y += shotsH + gap;
        steps.style.top = `${y}px`;
        y += stepsH + gap;
        cta.style.top = `${y}px`;
        const stepsBottom = cta.getBoundingClientRect().bottom;
        return { headBottom, free, stepsBottom, footTop: H - foot, width };
      }, { W: f.W, H: f.H, square: f.W === f.H });

      // The wall: local project titles, at the largest size that fits.
      const font = await page.evaluate((entries) => {
        const wall = document.getElementById('wall')!;
        wall.innerHTML = entries.join('');
        let lo = 6, hi = 30;
        for (let i = 0; i < 18; i++) {
          const mid = (lo + hi) / 2;
          wall.style.fontSize = `${mid}px`;
          if (wall.scrollHeight <= wall.clientHeight + 0.5) lo = mid;
          else hi = mid;
        }
        wall.style.fontSize = `${lo}px`;
        return lo;
      }, data.wall);

      if (lay.stepsBottom > lay.footTop) {
        throw new Error(`${f.key}: the visit band runs into the footer (${Math.round(lay.stepsBottom - lay.footTop)}px).`);
      }
      const overflows = await page.evaluate(() =>
        [...document.querySelectorAll<HTMLElement>('.head, .steps, .cta span, .foot, .kick')]
          .filter((el) => el.scrollWidth > el.clientWidth + 2 || el.scrollHeight > el.clientHeight + 2)
          .map((el) => el.className));
      if (overflows.length) throw new Error(`${f.key}: content overflow in ${overflows.join(', ')}.`);
      if (await page.locator('h1 span').first().textContent() !== config.name) throw new Error('Poster title does not match the configured city.');
      const png = join(OUT, `${config.id}-transparency-portal-${f.key}.png`);
      const rendered = await page.screenshot({ path: png });
      // Keep the originally shared file paths current too.
      writeFileSync(join(OUT, `create-your-own-transparency-portal-${f.key}.png`), rendered);
      await page.close();
      console.log(`${f.key}: head ends ${Math.round(lay.headBottom)}, portal ${Math.round(lay.width)}px wide, visit band ends ${Math.round(lay.stepsBottom)} / footer ${Math.round(lay.footTop)}, wall ${data.projects} projects at ${font.toFixed(1)}px → ${png}`);
    }
  } finally {
    await browser.close();
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  exit(1);
});
